/**
 * Translation dictionaries for the player app.
 *
 * English is the source of truth: `TranslationKey` is derived from it, so
 * adding a key to `en` makes TypeScript demand it in every other locale.
 * Missing keys therefore cannot ship silently.
 */

import type { FlagCountry } from '@/constants/flags';
import * as lobbyModule from './modules/lobby';
import * as accountModule from './modules/account';
import * as rgModule from './modules/rg';
import * as legalModule from './modules/legal';
import * as contentModule from './modules/content';
import * as miscModule from './modules/misc';

export const LOCALES = ['en', 'ar', 'tr', 'hi', 'fr', 'ru', 'pt', 'es', 'it'] as const;

export type Locale = (typeof LOCALES)[number];

export interface LocaleMeta {
  code: Locale;
  label: string;
  /** Whose flag stands for the language in pickers (see assets/flags). */
  country: FlagCountry;
  /** Right-to-left script — flips the document direction. */
  rtl?: boolean;
}

export const LOCALE_META: LocaleMeta[] = [
  { code: 'en', label: 'English', country: 'GB' },
  { code: 'ar', label: 'العربية', country: 'SA', rtl: true },
  { code: 'tr', label: 'Türkçe', country: 'TR' },
  { code: 'hi', label: 'हिन्दी', country: 'IN' },
  { code: 'fr', label: 'Français', country: 'FR' },
  { code: 'ru', label: 'Русский', country: 'RU' },
  { code: 'pt', label: 'Português', country: 'PT' },
  { code: 'es', label: 'Español', country: 'ES' },
  { code: 'it', label: 'Italiano', country: 'IT' },
];

