const withModules = (locale: Exclude<Locale, 'en'>, core: PartialDictionary): PartialDictionary =>
  Object.assign({}, core, ...MODULES.map((m) => m.translations[locale]));

export const DICTIONARIES: Record<Locale, PartialDictionary> & { en: Dictionary } = {
  en,
  ar: withModules('ar', ar),
  tr: withModules('tr', tr),
  hi: withModules('hi', hi),
  fr: withModules('fr', fr),
  ru: withModules('ru', ru),
  pt: withModules('pt', pt),
  es: withModules('es', es),
  it: withModules('it', it),
};
